import React from 'react';

export default function ClientsSection() {
  const logos = [
    'https://ext.same-assets.com/498039404/3885122600.svg',
    'https://ext.same-assets.com/498039404/819240957.svg',
    'https://ext.same-assets.com/498039404/1116060412.svg',
    'https://ext.same-assets.com/498039404/1651774368.svg',
    'https://ext.same-assets.com/498039404/1256259955.svg',
    'https://ext.same-assets.com/498039404/1956775689.svg',
    'https://ext.same-assets.com/498039404/1092326729.svg',
    'https://ext.same-assets.com/498039404/917814462.svg',
  ];

  return (
    <section className="py-20 container mx-auto px-6 lg:px-16">
      <div className="max-w-7xl mx-auto">
        <div className="flex items-center gap-4 mb-12">
          <span className="text-sm text-gray-400">// My Client</span>
          <div className="flex-1 h-px bg-gray-600"></div>
        </div>
        <h2 className="text-4xl lg:text-5xl font-bold mb-16 text-white">Worked With Amazing Clients</h2>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-8 items-center opacity-60">
          {logos.map((logo, index) => (
            <div key={index} className="flex justify-center">
              <img src={logo || '/placeholder.svg'} alt={`Client ${index + 1}`} className="h-8 w-auto transition-opacity duration-300 hover:opacity-100" />
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
